mkdir -p /tmp/pricing_check && cat > /tmp/pricing_check/check.py <<'EOF'
import csv, sys, importlib.util
from collections import Counter
from decimal import Decimal
src = sys.argv[1]
spec = importlib.util.spec_from_file_location("price", f"{src}/price.py")
p = importlib.util.module_from_spec(spec); spec.loader.exec_module(p)

# Build the single matrix: one row per zone, one column per band upper bound.
bounds = [hi for _, _, hi, _ in p.BANDS]
matrix = {z: {} for z in p.ZONES}
for z in p.ZONES:
    for b, lo, hi, _ in p.BANDS:
        matrix[z][hi] = p.price(z, lo)
print("zone," + ",".join(f"{h:g}" for h in bounds))
for z, row in matrix.items():
    print(z + "," + ",".join(str(row[h]) for h in bounds))

def new_price(zone, w):
    lo = 0.0
    for hi in bounds:
        if lo <= w < hi:
            return matrix[zone][hi]
        lo = hi
    raise ValueError(w)

rows = list(csv.DictReader(open(f"{src}/orders_2026-09.csv")))
mism, errs, zones, weights = [], Counter(), Counter(), []
old_total = new_total = Decimal(0)
surcharged = 0
for r in rows:
    z, w = r["zone"], float(r["weight_kg"])
    zones[z] += 1; weights.append(w)
    try:
        o = p.price(z, w)
    except Exception as e:
        errs[f"old {type(e).__name__}: {e}"] += 1; o = None
    try:
        n = new_price(z, w)
    except Exception as e:
        errs[f"new {type(e).__name__}: {e}"] += 1; n = None
    if o is not None and n is not None:
        old_total += o; new_total += n
        if o != n: mism.append((r["order_id"], z, w, o, n))
    if z in p.REMOTE_ZONES and o is not None and p.band_for(w) in p.HEAVY_BANDS:
        surcharged += 1
print("orders", len(rows), "mismatches", len(mism), "errors", dict(errs))
print("totals", old_total, new_total)
print("zones", dict(sorted(zones.items())))
print("weight min/max", min(weights), max(weights))
print("on band boundaries", sum(1 for w in weights if w in bounds or w == 0))
print("remote+heavy (surcharged)", surcharged)
for m in mism[:10]: print(m)
EOF
python3 -I /tmp/pricing_check/check.py /tmp/tmppmoy7vo6
